package ru.fifth.horror.client;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.util.math.BlockPos;import ru.fifth.horror.cutscene.CutsceneDefinition;
public final class VhsPlayback{private static boolean active;private static int ticks,mode;private static BlockPos tvPos;private VhsPlayback(){}public static void start(CutsceneDefinition scene,int m,BlockPos tv){active=true;ticks=0;mode=m;tvPos=tv;if(mode==0){CutsceneDefinition copy=scene;copy.teleportPlayerAtEnd=false;copy.hideHud=true;copy.lockInput=true;CutscenePlayback.start(copy);}MinecraftClient mc=MinecraftClient.getInstance();try{mc.gameRenderer.loadPostProcessor(new net.minecraft.util.Identifier("fiven","shaders/post/vhs.json"));}catch(Exception ignored){}}
public static void tick(){if(!active)return;ticks++;if(mode==0&&!CutscenePlayback.active())stop();if(ticks>20*120)stop();}public static void stop(){active=false;MinecraftClient mc=MinecraftClient.getInstance();try{mc.gameRenderer.disablePostProcessor();}catch(Exception ignored){}}public static void render(DrawContext c){if(!active)return;int w=c.getScaledWindowWidth(),h=c.getScaledWindowHeight();for(int y=(ticks%7);y<h;y+=7)c.fill(0,y,w,y+1,0x18000000);int noise=(ticks*37)%w;c.fill(noise,0,Math.min(w,noise+2),h,0x10FFFFFF);if(mode==1){int bw=Math.min(420,w-20),bh=Math.min(250,h-20),x=(w-bw)/2,y=(h-bh)/2;c.fill(x,y,x+bw,y+bh,0xEE050505);c.drawCenteredTextWithShadow(MinecraftClient.getInstance().textRenderer,"VHS / TV MODE",w/2,y+10,0xFFB8B8B8);c.drawCenteredTextWithShadow(MinecraftClient.getInstance().textRenderer,"REC",w/2,y+bh-20,0xFF8C2020);}}}
